{
  "status": "SUPPORTED",
  "task_summary": "Set up two refreshment stations near seating and relocate a remote control to a central accessible location.",
  "task_contract": {
    "functional_roles": [
      {
        "id": "refreshment_setting",
        "entity_kind": "OBJECT",
        "function": "Holds consumables for one person",
        "required_count": 2,
        "binding_policy": "DISTINCT"
      ,
      "candidate_categories": ["cup", "plate", "napkin"],
      "required_properties": ["holds_beverage_or_food"]
      }
    ,
      {
        "id": "entertainment_control",
        "entity_kind": "OBJECT",
        "function": "Operates the television",
        "required_count": 1,
        "binding_policy": "REUSABLE"
      ,
        "candidate_categories": ["remote_control"],
        "required_properties": ["operates_tv"]
      }
    ,
      {
        "id": "seating_position",
        "entity_kind": "REGION",
        "function": "Location where a person sits",
        "required_count": 2,
        "binding_policy": "DISTINCT"
      ,
        "candidate_categories": ["armchair", "sofa"],
        "required_properties": ["supports_person"]
      }
    ,
      {
        "id": "accessible_surface",
        "entity_kind": "REGION",
        "function": "Flat area within reach of seated people",
        "required_count": 1,
        "binding_policy": "SHARED"
      ,
        "candidate_categories": ["table", "side_table", "floor"],
        "required_properties": ["flat", "within_reach"]
      }
    ]
  ,
    "functional_relations": [
      {
        "id": "nearby_refreshment",
        "relation": "PROXIMITY",
        "participant_roles": ["refreshment_setting", "seating_position"],
        "required": true
      }
    ,
      {
        "id": "accessible_control",
        "relation": "REACHABILITY",
        "participant_roles": ["entertainment_control", "seating_position"],
        "required": true
      }
    ]
  ,
    "operation_pairings": [
      {
        "id": "set_refreshment",
        "operation": "PLACE",
        "participant_roles": ["refreshment_setting", "accessible_surface"],
        "operation_count": 2
      }
    ,
      {
        "id": "move_control",
        "operation": "MOVE_TO",
        "participant_roles": ["entertainment_control", "accessible_surface"],
        "operation_count": 1
      }
    ]
  }
  ,
